// The sign-in / sign-up dialog, shared by the header button and every page that needs a signed-in person. It is
// loaded on first use (it pulls in supabase-js).
// A native <dialog> opened with showModal() sits in the browser's top layer, so Squarespace's header
// (transforms, z-indexes, overflow) cannot clip or cover it.
// When someone signs in, <rgai-auth> fires `rgai-auth-changed` (bubbling, composed), which reaches window: the
// header button and the story-review app both listen for it there.
import '../story-review/components/auth-component';

export type AuthDialogMode = 'login' | 'signup';

const css = `
dialog.rg-auth-dialog {
  border: none; padding: 0; background: transparent; max-width: min(440px, calc(100vw - 2rem)); width: 100%;
  overflow: visible;
}
dialog.rg-auth-dialog::backdrop { background: rgba(15, 23, 42, 0.55); }
dialog.rg-auth-dialog .rg-auth-close {
  position: absolute; top: 0.6rem; right: 0.6rem; z-index: 1; width: 2rem; height: 2rem; border-radius: 999px;
  border: none; background: transparent; color: #64748b; font: 1.4rem/1 system-ui, sans-serif; cursor: pointer;
}
dialog.rg-auth-dialog .rg-auth-close:hover { background: #f1f5f9; color: #0f172a; }
dialog.rg-auth-dialog .rg-auth-wrap { position: relative; }
`;

let dialog: HTMLDialogElement | null = null;

function build(): HTMLDialogElement {
  if (!document.getElementById('rg-auth-dialog-css')) {
    const style = document.createElement('style');
    style.id = 'rg-auth-dialog-css';
    style.textContent = css;
    document.head.appendChild(style);
  }
  const d = document.createElement('dialog');
  d.className = 'rg-auth-dialog';
  d.setAttribute('aria-label', 'Sign in or create an account');
  d.innerHTML = `<div class="rg-auth-wrap"><button type="button" class="rg-auth-close" aria-label="Close">×</button></div>`;
  d.querySelector('.rg-auth-close')!.addEventListener('click', () => d.close());
  // A click on the backdrop (the dialog element itself, outside the card) closes it.
  d.addEventListener('click', (e) => {
    if (e.target === d) d.close();
  });
  d.addEventListener('rgai-auth-changed', () => d.close());
  document.body.appendChild(d);
  return d;
}

/** Opens the dialog with a fresh form (nothing typed last time is kept), on the Sign In or the Sign Up tab. */
export function openAuthDialog(mode: AuthDialogMode = 'login'): void {
  if (!dialog || !dialog.isConnected) dialog = build();
  const form = document.createElement('rgai-auth');
  form.setAttribute('mode', mode);
  form.style.cssText = 'margin:0;max-width:none';
  dialog.querySelector('rgai-auth')?.remove();
  dialog.querySelector('.rg-auth-wrap')!.appendChild(form);
  if (!dialog.open) dialog.showModal();
}

/** Signs out everywhere on the page: signOutAndClearSession fires `rgai-auth-changed` with no user. */
export async function signOut(): Promise<void> {
  const { signOutAndClearSession } = await import('../common/auth-utils');
  await signOutAndClearSession();
}
