import { BaseElement } from '../../common/base-element';
import { getSupabaseClient } from '../../common/supabase-client';

const styles = `
:host {
  display: block;
  font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
  color: #1a1a1a;
  max-width: 420px;
  margin: 2rem auto;
  box-sizing: border-box;
}

*, *::before, *::after {
  box-sizing: border-box;
}

.auth-card {
  background: #ffffff;
  border: 1px solid #e2e8f0;
  border-radius: 12px;
  padding: 2rem;
  box-shadow: 0 4px 6px -1px rgba(0, 0, 0, 0.05), 0 2px 4px -1px rgba(0, 0, 0, 0.03);
}

.auth-title {
  font-size: 1.5rem;
  font-weight: 700;
  margin: 0 0 0.5rem 0;
  text-align: center;
  color: #0f172a;
}

.auth-subtitle {
  font-size: 0.875rem;
  color: #64748b;
  margin: 0 0 1.5rem 0;
  text-align: center;
}

.auth-tabs {
  display: flex;
  border-bottom: 2px solid #e2e8f0;
  margin-bottom: 1.5rem;
}

.auth-tab {
  flex: 1;
  padding: 0.5rem 0;
  background: none;
  border: none;
  font-size: 0.95rem;
  font-weight: 600;
  color: #64748b;
  cursor: pointer;
  border-bottom: 2px solid transparent;
  margin-bottom: -2px;
  transition: all 0.15s ease;
}

.auth-tab.active {
  color: #0284c7;
  border-bottom-color: #0284c7;
}

.form-group {
  margin-bottom: 1.25rem;
}

label {
  display: block;
  font-size: 0.875rem;
  font-weight: 500;
  margin-bottom: 0.35rem;
  color: #334155;
}

input[type="text"],
input[type="email"],
input[type="password"] {
  width: 100%;
  padding: 0.65rem 0.85rem;
  border: 1px solid #cbd5e1;
  border-radius: 6px;
  font-size: 0.95rem;
  outline: none;
  transition: border-color 0.15s ease, box-shadow 0.15s ease;
}

/* The password field has a show/hide button inside it, on the right. */
.password-wrap {
  position: relative;
}

.password-wrap input {
  padding-right: 2.75rem;
}

/* Edge draws its own reveal button: ours replaces it. */
.password-wrap input::-ms-reveal {
  display: none;
}

.btn-reveal {
  position: absolute;
  top: 50%;
  right: 0.35rem;
  transform: translateY(-50%);
  width: 2.1rem;
  height: 2.1rem;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  padding: 0;
  border: none;
  border-radius: 6px;
  background: none;
  color: #64748b;
  cursor: pointer;
}

.btn-reveal:hover {
  color: #0f172a;
  background: #f1f5f9;
}

.btn-reveal:focus-visible {
  outline: 2px solid #0284c7;
  outline-offset: 1px;
}

.btn-reveal svg {
  width: 1.2rem;
  height: 1.2rem;
}

input:focus {
  border-color: #0284c7;
  box-shadow: 0 0 0 3px rgba(2, 132, 199, 0.15);
}

.btn-primary {
  width: 100%;
  padding: 0.75rem;
  background-color: #0284c7;
  color: #ffffff;
  border: none;
  border-radius: 6px;
  font-size: 0.95rem;
  font-weight: 600;
  cursor: pointer;
  transition: background-color 0.15s ease;
  margin-top: 0.5rem;
}

.btn-primary:hover:not(:disabled) {
  background-color: #0369a1;
}

.btn-primary:disabled {
  opacity: 0.6;
  cursor: not-allowed;
}

.auth-msg {
  padding: 0.75rem;
  border-radius: 6px;
  font-size: 0.875rem;
  margin-bottom: 1rem;
  display: none;
}

.auth-msg.error {
  display: block;
  background-color: #fef2f2;
  color: #991b1b;
  border: 1px solid #fecaca;
}

.auth-msg.success {
  display: block;
  background-color: #f0fdf4;
  color: #166534;
  border: 1px solid #bbf7d0;
}

.forgot-link {
  display: inline-block;
  margin-top: 0.5rem;
  font-size: 0.8rem;
  color: #0284c7;
  text-decoration: none;
  cursor: pointer;
}
.forgot-link:hover {
  text-decoration: underline;
}
`;

const EYE = `<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M2.5 12S6 5.5 12 5.5 21.5 12 21.5 12 18 18.5 12 18.5 2.5 12 2.5 12z"/><circle cx="12" cy="12" r="3"/></svg>`;
const EYE_OFF = `<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M2.5 12S6 5.5 12 5.5 21.5 12 21.5 12 18 18.5 12 18.5 2.5 12 2.5 12z"/><circle cx="12" cy="12" r="3"/><path d="M4 4l16 16"/></svg>`;

export class RgaiAuthElement extends BaseElement {
  private mode: 'login' | 'signup' | 'reset' = 'login';
  private loading = false;

  constructor() {
    super(styles);
  }

  connectedCallback() {
    // mode="signup" opens on the Sign Up tab (the "Create an account" buttons); anything else on Sign In.
    if (this.getAttribute('mode') === 'signup') this.mode = 'signup';
    this.render();
  }

  private setMode(mode: 'login' | 'signup' | 'reset') {
    this.mode = mode;
    this.render();
  }

  private render() {
    this.root.innerHTML = `
      <div class="auth-card">
        <h2 class="auth-title">${
          this.mode === 'login'
            ? 'Sign In'
            : this.mode === 'signup'
            ? 'Create Account'
            : 'Reset Password'
        }</h2>
        <p class="auth-subtitle">One Real Good AI account for the whole site</p>

        <div class="auth-tabs" style="${this.mode === 'reset' ? 'display: none;' : ''}">
          <button type="button" class="auth-tab ${this.mode === 'login' ? 'active' : ''}" id="tab-login">Sign In</button>
          <button type="button" class="auth-tab ${this.mode === 'signup' ? 'active' : ''}" id="tab-signup">Sign Up</button>
        </div>

        <div id="msg" class="auth-msg"></div>

        <form id="auth-form">
          ${
            this.mode === 'signup'
              ? `
              <div class="form-group">
                <label for="display-name">Display Name</label>
                <input type="text" id="display-name" required placeholder="How you want to be known" />
              </div>
            `
              : ''
          }
          <div class="form-group">
            <label for="email">Email Address</label>
            <input type="email" id="email" required placeholder="you@example.com" />
          </div>

          ${
            this.mode !== 'reset'
              ? `
              <div class="form-group">
                <label for="password">Password</label>
                <div class="password-wrap">
                  <input type="password" id="password" required minlength="6" placeholder="••••••••" autocomplete="${this.mode === 'signup' ? 'new-password' : 'current-password'}" />
                  <button type="button" class="btn-reveal" id="btn-reveal" aria-label="Show password" aria-pressed="false">${EYE}</button>
                </div>
                ${
                  this.mode === 'login'
                    ? `<a class="forgot-link" id="link-forgot">Forgot password?</a>`
                    : ''
                }
              </div>
            `
              : ''
          }

          <button type="submit" class="btn-primary" id="btn-submit" ${this.loading ? 'disabled' : ''}>
            ${
              this.loading
                ? 'Processing...'
                : this.mode === 'login'
                ? 'Sign In'
                : this.mode === 'signup'
                ? 'Create Account'
                : 'Send Reset Link'
            }
          </button>
        </form>

        ${
          this.mode === 'reset'
            ? `<div style="text-align: center; margin-top: 1rem;"><a class="forgot-link" id="link-back-login">Back to Sign In</a></div>`
            : ''
        }
      </div>
    `;

    this.bindEvents();
  }

  private bindEvents() {
    this.$('#tab-login')?.addEventListener('click', () => this.setMode('login'));
    this.$('#tab-signup')?.addEventListener('click', () => this.setMode('signup'));
    this.$('#link-forgot')?.addEventListener('click', () => this.setMode('reset'));
    this.$('#link-back-login')?.addEventListener('click', () => this.setMode('login'));
    this.$('#btn-reveal')?.addEventListener('click', () => this.togglePassword());

    this.$('#auth-form')?.addEventListener('submit', (e) => {
      e.preventDefault();
      this.handleSubmit();
    });
  }

  private async handleSubmit() {
    const email = (this.$<HTMLInputElement>('#email')?.value || '').trim();
    const password = this.$<HTMLInputElement>('#password')?.value || '';
    const displayName = (this.$<HTMLInputElement>('#display-name')?.value || '').trim();

    if (!email) return;

    this.loading = true;
    this.render();

    try {
      const supabase = getSupabaseClient();

      if (this.mode === 'login') {
        const { error, data } = await supabase.auth.signInWithPassword({ email, password });
        if (error) throw error;
        this.emit('rgai-auth-changed', { user: data.user, session: data.session });
      } else if (this.mode === 'signup') {
        const { error, data } = await supabase.auth.signUp({
          email,
          password,
          options: {
            data: { display_name: displayName || email.split('@')[0] },
          },
        });
        if (error) throw error;
        if (data.session) {
          this.emit('rgai-auth-changed', { user: data.user, session: data.session });
        } else {
          this.showMsg('Account created! Please check your email to confirm your account.', 'success');
        }
      } else if (this.mode === 'reset') {
        const { error } = await supabase.auth.resetPasswordForEmail(email, {
          // back to the page the person is on (the account page URL is the organizers' choice, so it is not hard-coded)
          redirectTo: `${window.location.origin}${window.location.pathname}`,
        });
        if (error) throw error;
        this.showMsg('Password reset link sent! Check your inbox.', 'success');
      }
    } catch (err: unknown) {
      const msg = err instanceof Error ? err.message : String(err);
      this.showMsg(msg, 'error');
    } finally {
      this.loading = false;
      const btn = this.$<HTMLButtonElement>('#btn-submit');
      if (btn) btn.disabled = false;
    }
  }

  /** Shows or hides the password as typed; the caret stays where it was. */
  private togglePassword() {
    const input = this.$<HTMLInputElement>('#password');
    const btn = this.$<HTMLButtonElement>('#btn-reveal');
    if (!input || !btn) return;
    const show = input.type === 'password';
    const { selectionStart, selectionEnd } = input;
    input.type = show ? 'text' : 'password';
    btn.innerHTML = show ? EYE_OFF : EYE;
    btn.setAttribute('aria-label', show ? 'Hide password' : 'Show password');
    btn.setAttribute('aria-pressed', String(show));
    input.focus();
    input.setSelectionRange(selectionStart, selectionEnd);
  }

  private showMsg(text: string, type: 'error' | 'success') {
    const msgEl = this.$('#msg');
    if (!msgEl) return;
    msgEl.textContent = text;
    msgEl.className = `auth-msg ${type}`;
  }
}

if (!customElements.get('rgai-auth')) {
  customElements.define('rgai-auth', RgaiAuthElement);
}
